BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-8412'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='1T1460' OR source_url ~ '[?&]id=8412(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='d3301460-44cb-4a85-af37-947116008412' OR slug='sam-sai-noi-land-54-rai-1t1460' OR (abs(latitude-13.99566)<0.0001 AND abs(longitude-100.32616)<0.0001 AND abs(land_area_sqm-87551.2)<1)) THEN RAISE NOTICE 'SAM 1T1460 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('d3301460-44cb-4a85-af37-947116008412', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'land', 'business', 'sale', 'whole_property', 'ที่ดิน 54 ไร่ 2 งาน 87.8 ตร.ว. ซอย กศน.บ้านคลองห้าร้อย ไทรน้อย', 'รายละเอียดทรัพย์

ที่ดินเปล่า 2 แปลงติดกัน ตำบลไทรน้อย อำเภอไทรน้อย จังหวัดนนทบุรี โฉนดเลขที่ 4885 และ 60808 (เลขเดิม 12065) เนื้อที่รวม 54 ไร่ 2 งาน 87.8 ตร.ว. หรือ 21,887.8 ตร.ว. (87,551.2 ตร.ม.) ราคาประกาศขายทั้งทรัพย์ 89,697,000 บาท รหัส SAM 1T1460 ต้นทางแสดงราคาเฉลี่ยประมาณ 4,098 บาทต่อ ตร.ว.

หน้าทรัพย์และสภาพที่ดิน

ทรัพย์เข้าจากถนนบางกรวย–ไทรน้อย (ทล.3215) ผ่านซอย อบต.ไทรน้อยเก่า โดยถนนหน้าทรัพย์คือซอย กศน.บ้านคลองห้าร้อย ไม่ใช่หน้าถนน ทล.3215 โดยตรง แปลงรวมรูปหลายเหลี่ยม ด้านตะวันตกติดถนนประมาณ 76 เมตร ลึกสุดประมาณ 1,028 เมตร ระดับที่ดินเฉลี่ยต่ำกว่าถนนประมาณ 1.6 เมตร ตาม SAM

มีบ่อน้ำ 2 บ่อ บ่อที่ 1 ขนาดประมาณ 11 × 580 เมตร ลึก 2 เมตร บ่อที่ 2 ประมาณ 5 × 62 เมตร ลึก 1 เมตร รวมพื้นที่บ่อตามต้นทางประมาณ 4 ไร่ 72.5 ตร.ว. ซึ่งอยู่ภายในเนื้อที่รวม ไม่ใช่พื้นที่เพิ่ม ควรตรวจระดับดิน การระบายน้ำ สภาพบ่อและพื้นที่ใช้งานจริงก่อนเสนอซื้อ

ถนนซอยหน้าทรัพย์ SAM ระบุเป็นทางสาธารณประโยชน์ ผิวลาดยางประมาณ 6 เมตร เขตทางประมาณ 16 เมตร ผังต้นทางระบายสีเทาบริเวณด้านหน้าและกำกับว่า “ส่วนที่มีสภาพเป็นทาง” แต่ไม่ระบุเนื้อที่หรือรายละเอียดสิทธิทางทะเบียนไว้ในข้อความ ควรตรวจแนวเขต การใช้ทางและพื้นที่ที่จะโอนจริง ไม่ตีความภาพผังเป็นการรับรองว่ามีหรือไม่มีภาระจำยอม

เอกสารสิทธิ์และการใช้ประโยชน์

โฉนด 4885 ระบุที่ตั้งตำบลไทรน้อย อำเภอบางบัวทอง จังหวัดนนทบุรี ส่วนโฉนด 60808 (12065 เดิม) ระบุอำเภอไทรน้อย (บางบัวทอง) ตาม SAM ขณะที่ประกาศใช้ที่ตั้งปัจจุบันเป็นอำเภอไทรน้อย ควรตรวจเลขโฉนดเดิม–ใหม่และชื่อเขตปกครองกับเอกสารปัจจุบัน

SAM ระบุผังเมืองสีเขียว ควรตรวจข้อกำหนดการใช้ประโยชน์ปัจจุบันตามกิจกรรมที่ต้องการ ต้นทางไม่ยืนยันผู้ใช้ประโยชน์ ภาระผูกพันล่าสุดหรือระบบสาธารณูปโภคภายในครบถ้วน

ทำเลและการเดินทาง

ตามต้นทางห่าง กศน.ไทรน้อยประมาณ 900 เมตร และบิ๊กซีไทรน้อยประมาณ 1.4 กม. ใช้ถนนบางกรวย–ไทรน้อยจากกาญจนาภิเษก ทล.9 มุ่งหน้า ทล.346 ผ่านโรงพยาบาลไทรน้อยและสถานีตำรวจ ถึงบริเวณ กม.26+100 เลี้ยวขวาเข้าซอย อบต.ไทรน้อยเก่าประมาณ 1.4 กม. คำบรรยายการเข้าถึงของ SAM ระบุพบทรัพย์ทั้งซ้ายและขวา ควรใช้ผังและตรวจแนวเขตจริงประกอบ ไม่สรุปตำแหน่งแปลงจากคำบอกทางเพียงอย่างเดียว

ภาพและการติดต่อ

ภาพจริงและผังจาก SAM รวม 10 ภาพ ภาพหน้าทรัพย์ลงวันที่ 14 มิถุนายน 2566 และภาพแปลง/บ่อน้ำมีวันที่ 24 พฤศจิกายน 2566 รวมภาพแยกเข้าซอยซึ่งไม่ใช่หน้าทรัพย์โดยตรง ควรนัดตรวจสภาพปัจจุบัน

พิกัด 13.99566, 100.32616 ดึงจากลิงก์นำทาง SAM และตรงกับแผนที่ เป็นจุดอ้างอิง ไม่ใช่แนวเขตรังวัด ตรวจราคาและสถานะซื้อตรงวันที่ 15 กันยายน 2569 ติดต่อ SAM โทร.02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 1T1460 เพื่อยืนยันราคา เอกสาร แนวเขตและเงื่อนไขล่าสุด', 89697000, false, 87551.2, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'ซอย กศน.บ้านคลองห้าร้อย', 'เข้าจากซอย อบต.ไทรน้อยเก่า ถนนบางกรวย–ไทรน้อย', 'ซอย กศน.บ้านคลองห้าร้อย', 13.99566, 100.32616, 'นนทบุรี', 'ไทรน้อย', 'ไทรน้อย', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-sai-noi-land-54-rai-1t1460') RETURNING id INTO property_listing_id;
