INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', '54 Rai Land in Sai Noi, Nonthaburi', 'Two adjoining vacant land plots in Sai Noi,Nonthaburi. Chanote4885and60808(former12065),total54rai2ngan87.8sq.wah,or21887.8sq.wah(87551.2sq.m.). SAM whole-property asking price THB89,697,000,reference1T1460;source approximate unit price THB4098/sq.wah.

Access from Bang Kruai–Sai Noi Highway3215 via the former Sai Noi local administration soi. Actual frontage is Soi Ko So No Ban Khlong Ha Roi,not Highway3215 itself. Irregular combined plot,approximately76m western road frontage and1028m maximum depth. Ground averages1.6m below road according to SAM.

Two ponds:approximately11by580m,2m deep,and5by62m,1m deep. Combined source pond area4rai72.5sq.wah is within total land,not additional area. Inspect levels,drainage,ponds and usable area. Source describes public frontage soi with6m paved carriageway and16m right of way. Source plan shades a frontage portion grey as land physically used as a road;area and registered rights are unspecified. Verify boundary,use/access and transferable area;the diagram does not establish existence or absence of a registered easement.

